# Secret leakage keywords — covers common secret types generated by the data pipeline.
# NOTE: A proper per-secret keyword index (secret_index.json) should be generated
# during data packaging for comprehensive coverage. This list is a pragmatic proxy.
SECRECY_KEYWORDS = [
    # Treasure / artifacts
    "chalice", "goblet", "vault location", "artifact", "relic", "crown",
    "scepter", "gem", "jewel", "treasure", "hoard",
    # Military / security
    "patrol schedule", "patrol route", "guard rotation", "watch change",
    "passphrase", "password", "weak point", "defense", "tunnel",
    # Financial / trade
    "ledger", "accounts", "smuggling", "contraband", "shipment",
    "cargo", "black market", "counterfeit", "bribe", "embezzlement",
    # Personal / political
    "affair", "scandal", "illegitimate", "bastard", "succession",
    "inheritance", "will", "testament", "alliance", "betrayal",
    # Supplies / theft
    "supply theft", "stolen", "thief", "heist", "cache", "stash",
    # Religious / ideological
    "heresy", "blasphemy", "sacrilege", "prophecy", "omen",
    # Violence / crime
    "poison", "toxin", "venom", "assassin", "murder", "conspiracy",
    "corruption", "graft", "extortion", "blackmail",
]


def _load_predicted_zt_lookup(predicted_zt_file: str) -> dict[tuple[str, int], dict]:
    """Load predicted Z_t JSONL into a lookup keyed by (episode_id, turn_idx)."""
    lookup: dict[tuple[str, int], dict] = {}
    if not Path(predicted_zt_file).exists():
        return lookup
    with open(predicted_zt_file) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            rec = json.loads(line)
            ep = str(rec.get("episode_id", ""))
            turn = rec.get("turn_idx", rec.get("turn", 0))
            if ep:
                lookup[(ep, int(turn))] = rec
    return lookup


def _is_slow_path(state: dict) -> bool:
    """Check if predicted state triggers slow path (reuses eval_routing logic)."""
    D_t = {k: state.get(k, "") for k in ["response_policy", "reveal_decision"]}
    N_t = {k: state.get(k, "") for k in ["value_conflict", "secrecy_pressure"]}
    if N_t.get("value_conflict") == "strong":
        return True
    if N_t.get("secrecy_pressure") == "high" and D_t.get("reveal_decision") in {"hint", "partial", "full"}:
        return True
    if D_t.get("response_policy") in {"threaten", "negotiate"}:
        return True
    if D_t.get("reveal_decision") in {"hint", "partial", "full"}:
        return True
    return False


def eval_response(config_path: str) -> dict:
    with open(config_path) as f:
        cfg = yaml.safe_load(f)

    import mlflow
    from src.mlflow_utils import setup_mlflow

    setup_mlflow(cfg["mlflow"]["tracking_uri"])
    mlflow.set_experiment(cfg["mlflow"]["experiment_name"])

    checkpoint = cfg["response_checkpoint"]
    gen_cfg = cfg.get("generation", {})

    # Decision card configuration
    use_decision_card = cfg.get("decision_card", {}).get("enabled", False)
    pred_zt_lookup: dict[tuple[str, int], dict] = {}
    if use_decision_card:
        predicted_zt_file = cfg.get("predicted_zt_file", "")
        if predicted_zt_file and Path(predicted_zt_file).exists():
            pred_zt_lookup = _load_predicted_zt_lookup(predicted_zt_file)
            print(f"Decision card mode: loaded {len(pred_zt_lookup)} predicted states")
        else:
            print(f"[WARN] Decision card enabled but predicted_zt_file not found: {predicted_zt_file}")
            use_decision_card = False

    print(f"Loading response model from {checkpoint}")
    tokenizer = AutoTokenizer.from_pretrained(checkpoint, trust_remote_code=True)
    if tokenizer.pad_token is None:
        tokenizer.pad_token = tokenizer.eos_token

    model = AutoModelForCausalLM.from_pretrained(
        checkpoint,
        device_map="auto",
        torch_dtype=torch.bfloat16,
        trust_remote_code=True,
    )
    model.eval()

    test_ds = SFTDataset(
        cfg["data"]["test_sft_file"],
        tokenizer,
        max_seq_len=cfg.get("generation", {}).get("max_seq_len", 2048),
    )
    test_loader = DataLoader(
        test_ds, batch_size=1, shuffle=False,
        collate_fn=collate_sft_batch, num_workers=0,
    )

    results_dir = Path(cfg["output"]["results_dir"])
    results_dir.mkdir(parents=True, exist_ok=True)

    n_samples = cfg["output"].get("n_sample_generations", 100)
    generations: list[dict] = []

    # Leakage accounting.
    # - leak_gated_*  : restricted to turns where reveal_decision=none (the
    #   "should not reveal" subset). This is the safety-critical denominator.
    # - leak_ungated_*: any turn where a leakage keyword appears in both input
    #   and generation regardless of reveal_decision. This catches the previous
    #   0.0 vs 10/100 discrepancy between aggregate and per-sample reporting.
    leak_gated_pos = 0
    leak_gated_total = 0
    leak_ungated_pos = 0
    leak_per_reveal_decision: Counter = Counter()
    contradiction_flags = 0

    rouge_l_scores: list[float] = []
    episode_ids_for_bootstrap: list[str] = []
    gold_texts: list[str] = []
    generated_texts: list[str] = []
    prompt_texts: list[str] = []
    generated_lengths: list[int] = []
    reference_lengths: list[int] = []

    # Optional length-aware decoding: cap max_new_tokens at
    # length_multiplier * median(reference tokens). This directly attacks the
    # length_ratio=2.334 finding from the previous batch.
    length_aware = bool(gen_cfg.get("length_aware_max_tokens", False))
    length_multiplier = float(gen_cfg.get("length_multiplier", 1.3))
    static_max_new = int(gen_cfg.get("max_new_tokens", 128))
    median_ref_tokens = None
    if length_aware:
        ref_token_lens = []
        for rec in test_ds.records:
            tgt = rec.get("target", "")
            if tgt:
                ref_token_lens.append(len(tokenizer(tgt, add_special_tokens=False).input_ids))
        if ref_token_lens:
            median_ref_tokens = int(statistics.median(ref_token_lens))
            print(f"Length-aware decoding: median ref tokens={median_ref_tokens} -> cap={int(length_multiplier * median_ref_tokens)}")

    with torch.no_grad():
        for i, batch in enumerate(tqdm(test_loader, desc="Generating responses")):
            input_ids      = batch["input_ids"].to(model.device)
            attention_mask = batch["attention_mask"].to(model.device)

            # SFTDataset now returns prompt_len which separates context from target
            if "prompt_len" in batch:
                prompt_len = batch["prompt_len"][0].item()
                # Use only the prompt part for generation input
                generation_input_ids = input_ids[:, :prompt_len]
                attention_mask = attention_mask[:, :prompt_len]
            else:
                # Fallback if prompt_len is missing (though it shouldn't be)
                generation_input_ids = input_ids
            
            input_text = tokenizer.decode(generation_input_ids[0], skip_special_tokens=True)
            target_ids  = batch["labels"][0]
            target_mask = target_ids != -100
            gold_text   = tokenizer.decode(target_ids[target_mask], skip_special_tokens=True).strip()

            # Decision card: optionally replace prompt for slow-path turns
            used_decision_card = False
            decision_card_text = None
            if use_decision_card:
                ep_id = str(batch.get("episode_id", [""])[0])
                turn_idx = int(batch.get("turn_idx", [0])[0])
                pred_state = pred_zt_lookup.get((ep_id, turn_idx))
                if pred_state is not None and _is_slow_path(pred_state):
                    secret_strings = batch.get("secret_strings", [[]])[0]
                    if isinstance(secret_strings, str):
                        secret_strings = [secret_strings]
                    # Extract player utterance from original prompt for context
                    player_utt = input_text[-200:] if len(input_text) > 200 else input_text
                    decision_card_text = build_decision_card(
                        pred_state,
                        secret_strings=secret_strings,
                        player_utterance=player_utt,
                        npc_role="NPC",
                    )
                    # Re-tokenize the decision card as the new prompt
                    card_enc = tokenizer(
                        decision_card_text,
                        return_tensors="pt",
                        max_length=gen_cfg.get("max_seq_len", 2048),
                        truncation=True,
                    )
                    generation_input_ids = card_enc["input_ids"].to(model.device)
                    attention_mask = card_enc["attention_mask"].to(model.device)
                    used_decision_card = True

            if length_aware and median_ref_tokens is not None:
                max_new_tokens = max(16, int(length_multiplier * median_ref_tokens))
            else:
                max_new_tokens = static_max_new

            output_ids = model.generate(
                input_ids=generation_input_ids,
                attention_mask=attention_mask,
                max_new_tokens=max_new_tokens,
                temperature=gen_cfg.get("temperature", 0.7),
                top_p=gen_cfg.get("top_p", 0.92),
                repetition_penalty=gen_cfg.get("repetition_penalty", 1.15),
                no_repeat_ngram_size=gen_cfg.get("no_repeat_ngram_size", 3),
                do_sample=gen_cfg.get("do_sample", True),
                pad_token_id=tokenizer.pad_token_id,
            )

            new_tokens = output_ids[0, generation_input_ids.shape[1]:]
            generated = tokenizer.decode(new_tokens, skip_special_tokens=True).strip()

            rouge_l = _rouge_l(gold_text, generated)
            rouge_l_scores.append(rouge_l)
            episode_ids_for_bootstrap.append(str(batch.get("episode_id", [""])[0]))
            gold_texts.append(gold_text)
            generated_texts.append(generated)
            prompt_texts.append(input_text)
            generated_lengths.append(len(generated.split()))
            reference_lengths.append(len(gold_text.split()))

            leaks = _check_secret_leakage(input_text, generated)
            reveal_decision = _extract_reveal_decision(input_text)
            if leaks:
                leak_ungated_pos += 1
                leak_per_reveal_decision[reveal_decision or "unknown"] += 1
            if reveal_decision == "none":
                leak_gated_total += 1
                if leaks:
                    leak_gated_pos += 1

            if _check_contradiction(input_text, generated):
                contradiction_flags += 1

            if len(generations) < n_samples:
                gen_rec = {
                    "prompt": input_text,
                    "input_snippet": input_text[-300:],
                    "gold": gold_text,
                    "generated": generated,
                    "rouge_l": rouge_l,
                    "secret_leak": leaks,
                    "reveal_decision": reveal_decision,
                    "used_decision_card": used_decision_card,
                    "episode_id": str(batch.get("episode_id", [""])[0]),
                    "turn_idx": int(batch.get("turn_idx", [0])[0]),
                }
                if used_decision_card and decision_card_text:
                    gen_rec["decision_card"] = decision_card_text
                generations.append(gen_rec)

    del model
    if torch.cuda.is_available():
        torch.cuda.empty_cache()

    rouge_l_ci_low, rouge_l_ci_high = _bootstrap_mean_ci(
        rouge_l_scores, episode_ids=episode_ids_for_bootstrap
    )
    semantic_metrics = _compute_optional_semantic_metrics(
        gold_texts,
        generated_texts,
        prompts=prompt_texts,
        cfg=cfg.get("semantic_eval", {}),
    )

    # Decision card usage stats
    card_count = sum(1 for g in generations if g.get("used_decision_card"))
    metrics = {
        "rouge_l": sum(rouge_l_scores) / max(1, len(rouge_l_scores)),
        "rouge_l_ci_low": rouge_l_ci_low,
        "rouge_l_ci_high": rouge_l_ci_high,
        "bleu_1": _corpus_bleu(gold_texts, generated_texts, max_n=1),
        "bleu_2": _corpus_bleu(gold_texts, generated_texts, max_n=2),
        "bleu_4": _corpus_bleu(gold_texts, generated_texts, max_n=4),
        # Safety-critical gated rate (denominator: reveal_decision == "none").
        "secret_leakage_rate": leak_gated_pos / max(1, leak_gated_total),
        "secret_leakage_gated_count": leak_gated_pos,
        "secret_leakage_gated_total": leak_gated_total,
        # Ungated rate across all turns; this is what per-sample sample_generations
        # flags add up to and resolves the previous 0.0 vs 10/100 disagreement.
        "secret_leakage_rate_ungated": leak_ungated_pos / max(1, len(rouge_l_scores)),
        "secret_leakage_ungated_count": leak_ungated_pos,
        "secret_leakage_by_reveal_decision": dict(leak_per_reveal_decision),
        "contradiction_rate": contradiction_flags / max(1, len(rouge_l_scores)),
        "distinct_1": _distinct_n(generated_texts, 1),
        "distinct_2": _distinct_n(generated_texts, 2),
        "repeated_3gram_rate": _mean_repeated_ngram_rate(generated_texts, 3),
        "degenerate_repetition_rate": _degenerate_repetition_rate(generated_texts, n=3, threshold=0.25),
        "prompt_artifact_rate": _prompt_artifact_rate(generated_texts),
        "avg_len": sum(generated_lengths) / max(1, len(generated_lengths)),
        "avg_ref_len": sum(reference_lengths) / max(1, len(reference_lengths)),
        "length_ratio": (
            (sum(generated_lengths) / max(1, sum(reference_lengths))) if reference_lengths else 0.0
        ),
        "n_evaluated": len(rouge_l_scores),
        "decision_card_enabled": use_decision_card,
        "decision_card_count": card_count,
        **semantic_metrics,
    }

    bundle = {"summary": metrics}

    with open(results_dir / "response_eval_metrics.json", "w") as f:
        json.dump(bundle, f, indent=2)
    write_metrics_bundle(results_dir, "response_eval_report", bundle, title="Response Evaluation Report")

    if cfg["output"].get("save_sample_generations", True):
        with open(results_dir / "sample_generations.json", "w") as f:
            json.dump(generations, f, indent=2)

    scalar_summary = {
        k: v for k, v in bundle["summary"].items()
        if isinstance(v, (int, float, bool))
    }
    with mlflow.start_run(run_name="response_eval"):
        log_metrics_to_mlflow(scalar_summary, prefix="eval")
        mlflow.log_artifact(str(results_dir / "response_eval_metrics.json"))
        if (results_dir / "sample_generations.json").exists():
            mlflow.log_artifact(str(results_dir / "sample_generations.json"))
        mlflow.log_artifact(str(results_dir / "response_eval_report.md"))

    _print_summary(metrics, cfg["thresholds"])
    return metrics


def _rouge_l(reference: str, hypothesis: str) -> float:
    if not reference or not hypothesis:
        return 0.0
    ref_tokens = reference.lower().split()
    hyp_tokens = hypothesis.lower().split()
    lcs = _lcs_length(ref_tokens, hyp_tokens)
    if lcs == 0:
        return 0.0
    precision = lcs / len(hyp_tokens)
    recall    = lcs / len(ref_tokens)
    if precision + recall == 0:
        return 0.0
    return 2 * precision * recall / (precision + recall)


def _tokens(text: str) -> list[str]:
    return re.findall(r"\w+|[^\w\s]", text.lower(), flags=re.UNICODE)


def _corpus_bleu(references: list[str], hypotheses: list[str], max_n: int = 4) -> float:
    if not references or not hypotheses:
        return 0.0

    clipped_counts = [0] * max_n
    total_counts = [0] * max_n
    ref_len = 0
    hyp_len = 0

    for reference, hypothesis in zip(references, hypotheses):
        ref_tokens = _tokens(reference)
        hyp_tokens = _tokens(hypothesis)
        ref_len += len(ref_tokens)
        hyp_len += len(hyp_tokens)

        for n in range(1, max_n + 1):
            hyp_ngrams = Counter(tuple(hyp_tokens[i : i + n]) for i in range(max(0, len(hyp_tokens) - n + 1)))
            ref_ngrams = Counter(tuple(ref_tokens[i : i + n]) for i in range(max(0, len(ref_tokens) - n + 1)))
            clipped_counts[n - 1] += sum(min(count, ref_ngrams[ng]) for ng, count in hyp_ngrams.items())
            total_counts[n - 1] += sum(hyp_ngrams.values())

    if hyp_len == 0:
        return 0.0

    # Chen-Cherry style smoothing is overkill here; add-one smoothing keeps
    # the corpus BLEU stable for small eval samples with sparse higher n-grams.
    precisions = [
        (clipped_counts[i] + 1.0) / (total_counts[i] + 1.0)
        for i in range(max_n)
    ]
    brevity_penalty = 1.0 if hyp_len > ref_len else math.exp(1 - ref_len / max(1, hyp_len))
    return float(brevity_penalty * math.exp(sum(math.log(p) for p in precisions) / max_n))


def _bootstrap_mean_ci(values: list[float], n_bootstrap: int = 1000, seed: int = 13,
                        episode_ids: list[str] | None = None) -> tuple[float, float]:
    """Episode-level percentile bootstrap. Resamples episodes, not turns.

    If episode_ids is provided, values are grouped by episode and resampled
    at the episode level. This is required because multi-turn episodes are
    not independent observations.
    """
    if not values:
        return 0.0, 0.0
    rng = random.Random(seed)

    if episode_ids is not None and len(episode_ids) == len(values):
        # Episode-level bootstrap: group values by episode, resample episodes
        from collections import defaultdict
        episode_to_values: dict[str, list[float]] = defaultdict(list)
        for ep, v in zip(episode_ids, values):
            episode_to_values[ep].append(v)
        episodes = list(episode_to_values.keys())
        n_eps = len(episodes)
        means = []
        for _ in range(n_bootstrap):
            sample = []
            for _ in range(n_eps):
                ep = episodes[rng.randrange(n_eps)]
                sample.extend(episode_to_values[ep])
            means.append(sum(sample) / max(1, len(sample)))
    else:
        # Fallback: turn-level bootstrap (not recommended for episodic data)
        n = len(values)
        means = []
        for _ in range(n_bootstrap):
            sample_sum = sum(values[rng.randrange(n)] for _ in range(n))
            means.append(sample_sum / n)

    means.sort()
    low_idx = int(0.025 * (n_bootstrap - 1))
    high_idx = int(0.975 * (n_bootstrap - 1))
    return float(means[low_idx]), float(means[high_idx])


def _lcs_length(a: list, b: list) -> int:
    m, n = len(a), len(b)
    if m == 0 or n == 0:
        return 0
    prev = [0] * (n + 1)
    for i in range(1, m + 1):
        curr = [0] * (n + 1)
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                curr[j] = prev[j - 1] + 1
            else:
                curr[j] = max(curr[j - 1], prev[j])
        prev = curr
    return prev[n]


_REVEAL_RE = re.compile(r"(?:reveal_decision|reveal)\s*[:=]\s*([a-z_]+)", flags=re.IGNORECASE)
_VALENCE_RE = re.compile(r"A_t:.*?valence=([a-z_]+)", flags=re.IGNORECASE | re.DOTALL)


def _extract_reveal_decision(input_text: str) -> str | None:
    """Pull the reveal_decision value out of the structured prompt.

    Supports both `reveal_decision: hint` and `reveal_decision=hint` forms.
    Returns the lowercased value or None if absent.
    """
    m = _REVEAL_RE.search(input_text)
    if not m:
        return None
    return m.group(1).lower()


def _check_secret_leakage(input_text: str, generated: str) -> bool:
    generated_lower = generated.lower()
    for kw in SECRECY_KEYWORDS:
        if kw in input_text.lower() and kw in generated_lower:
            return True
    return False


def _check_contradiction(input_text: str, generated: str) -> bool:
    contradiction_patterns = [
        ("i know nothing", "i saw"),
        ("i was not there", "i watched"),
        ("there is no secret", "the secret"),
        ("i never met", "i have known"),
    ]
    gen_lower = generated.lower()
    for pat_a, pat_b in contradiction_patterns:
        if pat_a in input_text.lower() and pat_b in gen_lower:
            return True
    return False


def _print_summary(metrics: dict, thresholds: dict) -> None:
    leakage = metrics.get('secret_leakage_rate', 0)
    n_samples = metrics.get('n_evaluated', 100)
    # Wilson 95% CI upper bound for binomial proportion
    import math
    z = 1.96
    n = max(n_samples, 1)
    p = leakage
    denominator = 1 + z**2 / n
    centre = (p + z**2 / (2 * n)) / denominator
    margin = z * math.sqrt(p * (1 - p) / n + z**2 / (4 * n**2)) / denominator
    ci_upper = min(centre + margin, 1.0)
    
    ungated = metrics.get('secret_leakage_rate_ungated', 0)
    ungated_n = metrics.get('secret_leakage_ungated_count', 0)
    gated_n = metrics.get('secret_leakage_gated_count', 0)
    gated_total = metrics.get('secret_leakage_gated_total', 0)
    print("\n=== Response Generation Evaluation Summary ===")
    print(f"  ROUGE-L:             {metrics.get('rouge_l', 0):.4f}")
    print(f"  BLEU-4:              {metrics.get('bleu_4', 0):.4f}")
    if "bertscore_f1" in metrics:
        print(f"  BERTScore F1:        {metrics.get('bertscore_f1', 0):.4f}")
    if "mauve_score" in metrics:
        print(f"  MAUVE:               {metrics.get('mauve_score', 0):.4f}")
    if "sentiment_valence_accuracy" in metrics:
        print(f"  Sentiment/valence:   {metrics.get('sentiment_valence_accuracy', 0):.4f}")
    print(f"  Length ratio:        {metrics.get('length_ratio', 0):.3f}  (target ≈ 1.0)")
    print(f"  Repeated 3-grams:    {metrics.get('repeated_3gram_rate', 0):.4f}")
    print(f"  Prompt Artifacts:    {metrics.get('prompt_artifact_rate', 0):.4f}")
    print(f"  Secret Leakage (gated, reveal=none):   {leakage:.4f}  ({gated_n}/{gated_total})  (95% CI upper: {ci_upper:.4f})  (threshold ≤ {thresholds.get('secret_leakage_rate', 0.05)})")
    print(f"  Secret Leakage (ungated, all turns):   {ungated:.4f}  ({ungated_n}/{n_samples})")
    print(f"  Contradiction Rate:  {metrics.get('contradiction_rate', 0):.4f}  (threshold ≤ {thresholds.get('contradiction_rate', 0.08)})")
    if metrics.get("decision_card_enabled"):
        print(f"  Decision Cards:      {metrics.get('decision_card_count', 0)} slow-path prompts replaced")
    print()


def _distinct_n(texts: list[str], n: int) -> float:
    ngrams = []
    for text in texts:
        tokens = text.lower().split()
        if len(tokens) < n:
            continue
        ngrams.extend(tuple(tokens[i : i + n]) for i in range(len(tokens) - n + 1))
    if not ngrams:
        return 0.0
    return len(set(ngrams)) / len(ngrams)


def _repeated_ngram_rate(text: str, n: int = 3) -> float:
    tokens = _tokens(text)
    if len(tokens) < n:
        return 0.0
    ngrams = [tuple(tokens[i : i + n]) for i in range(len(tokens) - n + 1)]
    counts = Counter(ngrams)
    repeated = sum(count - 1 for count in counts.values() if count > 1)
    return repeated / max(1, len(ngrams))


def _mean_repeated_ngram_rate(texts: list[str], n: int = 3) -> float:
    if not texts:
        return 0.0
    return float(sum(_repeated_ngram_rate(text, n) for text in texts) / len(texts))


def _degenerate_repetition_rate(texts: list[str], n: int = 3, threshold: float = 0.25) -> float:
    if not texts:
        return 0.0
    return float(sum(_repeated_ngram_rate(text, n) >= threshold for text in texts) / len(texts))


def _prompt_artifact_rate(texts: list[str]) -> float:
    if not texts:
        return 0.0
    patterns = [
        r"</?(response|scene|emotion|speech)>",
        r"\bbased on the\b",
        r"\bokay,\s+let'?s see\b",
        r"\bthe response should\b",
        r"\bgenerate npc response\b",
    ]
    artifact_re = re.compile("|".join(patterns), flags=re.IGNORECASE)
    return float(sum(bool(artifact_re.search(text)) for text in texts) / len(texts))


def _compute_optional_semantic_metrics(
    references: list[str],
    hypotheses: list[str],
    prompts: list[str],
    cfg: dict,
) -> dict:
    """Compute optional heavyweight semantic/affective metrics.

    These are useful for paper analysis when dependencies and model caches are
    available, but missing packages should not make the core evaluator fail.
    """
    if not cfg or not bool(cfg.get("enabled", False)):
        return {}

    references = [text if text.strip() else "." for text in references]
    hypotheses = [text if text.strip() else "." for text in hypotheses]
    metrics: dict = {}
    skip_reasons: dict[str, str] = {}

    if bool(cfg.get("bertscore", True)):
        try:
            from bert_score import score as bert_score

            p, r, f1 = bert_score(
                hypotheses,
                references,
                lang=cfg.get("bertscore_lang", "en"),
                model_type=cfg.get("bertscore_model_type"),
                batch_size=int(cfg.get("batch_size", 8)),
                verbose=False,
                rescale_with_baseline=bool(cfg.get("bertscore_rescale_with_baseline", False)),
            )
            metrics["bertscore_precision"] = float(p.mean().item())
            metrics["bertscore_recall"] = float(r.mean().item())
            metrics["bertscore_f1"] = float(f1.mean().item())
        except Exception as e:
            skip_reasons["bertscore"] = str(e)

    if bool(cfg.get("mauve", False)):
        try:
            import mauve

            device_id = int(cfg.get("mauve_device_id", 0 if torch.cuda.is_available() else -1))
            out = mauve.compute_mauve(
                p_text=references,
                q_text=hypotheses,
                device_id=device_id,
                max_text_length=int(cfg.get("mauve_max_text_length", 256)),
                verbose=False,
            )
            metrics["mauve_score"] = float(out.mauve)
        except Exception as e:
            skip_reasons["mauve"] = str(e)

    if bool(cfg.get("sentiment_alignment", True)):
        sentiment_metrics, sentiment_error = _compute_sentiment_alignment(
            hypotheses,
            prompts,
            model_name=cfg.get("sentiment_model", "cardiffnlp/twitter-roberta-base-sentiment-latest"),
            batch_size=int(cfg.get("batch_size", 8)),
        )
        metrics.update(sentiment_metrics)
        if sentiment_error:
            skip_reasons["sentiment_alignment"] = sentiment_error

    if skip_reasons:
        metrics["semantic_eval_skipped"] = skip_reasons
    return metrics


def _extract_target_valence(prompt: str) -> str | None:
    m = _VALENCE_RE.search(prompt or "")
    if not m:
        return None
    val = m.group(1).lower()
    return val if val in {"negative", "neutral", "positive"} else None


def _normalise_sentiment_label(label: str) -> str | None:
    label = (label or "").lower()
    if "positive" in label or label in {"label_2", "2"}:
        return "positive"
    if "negative" in label or label in {"label_0", "0"}:
        return "negative"
    if "neutral" in label or label in {"label_1", "1"}:
        return "neutral"
    return None


def _compute_sentiment_alignment(
    hypotheses: list[str],
    prompts: list[str],
    *,
    model_name: str,
    batch_size: int,
) -> tuple[dict, str | None]:
    target_valences = [_extract_target_valence(prompt) for prompt in prompts]
    valid_indices = [i for i, val in enumerate(target_valences) if val is not None]
    if not valid_indices:
        return {"sentiment_valence_support": 0}, None

    try:
        from transformers import pipeline

        device = 0 if torch.cuda.is_available() else -1
        classifier = pipeline(
            "text-classification",
            model=model_name,
            tokenizer=model_name,
            device=device,
            truncation=True,
        )
        texts = [hypotheses[i] for i in valid_indices]
        outputs = classifier(texts, batch_size=batch_size)
    except Exception as e:
        return {}, str(e)

    predicted = []
    gold = []
    for idx, out in zip(valid_indices, outputs):
        if isinstance(out, list):
            out = out[0] if out else {}
        pred = _normalise_sentiment_label(str(out.get("label", ""))) if isinstance(out, dict) else None
        if pred is None:
            continue
        predicted.append(pred)
        gold.append(target_valences[idx])

    if not gold:
        return {"sentiment_valence_support": 0}, None

    matches = sum(p == g for p, g in zip(predicted, gold))
    pred_counts = Counter(predicted)
    gold_counts = Counter(gold)
    return {
        "sentiment_valence_accuracy": matches / max(1, len(gold)),
        "sentiment_valence_support": len(gold),
        "sentiment_valence_pred_negative": pred_counts.get("negative", 0),
        "sentiment_valence_pred_neutral": pred_counts.get("neutral", 0),
        "sentiment_valence_pred_positive": pred_counts.get("positive", 0),
        "sentiment_valence_gold_negative": gold_counts.get("negative", 0),
        "sentiment_valence_gold_neutral": gold_counts.get("neutral", 0),
        "sentiment_valence_gold_positive": gold_counts.get("positive", 0),
    }, None
